          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      expect(
        screen.queryByLabelText("Info With Circle Icon"),
      ).not.toBeInTheDocument();
    });
  });
});

import {
  ReactNode,
  createContext,
  useCallback,
  useContext,
  useMemo,
} from "react";
import {
  ToastProvider as LGToastProvider,
  Variant,
  useToast,
} from "@leafygreen-ui/toast";
import { WordBreak } from "../../components/styles";
import {
  TOAST_TIMEOUT,
  mapLeafyGreenVariantToTitle,
  mapLeafyGreenVariantToToast,
} from "./constants";
import { DispatchToast, DispatchToastWithProgress, ToastParams } from "./types";

interface ToastContextState {
  success: DispatchToast;
  warning: DispatchToast;
  error: DispatchToast;
  info: DispatchToast;
  progress: DispatchToastWithProgress;
}

export const ToastContext = createContext<ToastContextState | null>(null);

const useToastContext = (): ToastContextState => {
  const context = useContext(ToastContext);
  if (context === null || context === undefined) {
    throw new Error("useToastContext must be used within a ToastProvider");
  }
  return context;
};

const ToastProviderCore: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { pushToast } = useToast();
  const dispatchToast = useCallback(
    ({
      closable,
      message,
      onClose,
      progress,
      shouldTimeout,
      timeout,
      title,
      variant,
    }: ToastParams) => {
      let toastTimeout = null;
      if (timeout !== undefined) {
        toastTimeout = timeout;
      } else if (shouldTimeout) {
        toastTimeout = TOAST_TIMEOUT;
      }

      return pushToast({
        // @ts-expect-error: data-cy doesn't exist as a prop on Toast but it will be propagated correctly.
        "data-cy": "toast",
        "data-variant": mapLeafyGreenVariantToToast[variant],
        description: <WordBreak>{message}</WordBreak>,
        dismissible: closable,
        onClose: closable ? onClose : undefined,
        progress,
        timeout: toastTimeout,
        title: title || mapLeafyGreenVariantToTitle[variant],
        variant,
      });
    },
    [pushToast],
  );

  const toastContext: ToastContextState = useMemo(() => {
    const defaultOptions = {
      onClose: () => {},
      shouldTimeout: true,
      title: "",
    };

    return {
      error: (message = "", closable = true, options = {}) =>
        dispatchToast({
          closable,
          message,
          variant: Variant.Warning,
          ...defaultOptions,
          ...options,
        }),
      info: (message = "", closable = true, options = {}) =>
        dispatchToast({
          closable,
          message,
          variant: Variant.Note,
          ...defaultOptions,
          ...options,
        }),
      progress: (message = "", progress = 0.5, closable = true, options = {}) =>
        dispatchToast({
          closable,
          message,
          progress,
          variant: Variant.Progress,
          ...defaultOptions,
          ...options,
        }),
      success: (message = "", closable = true, options = {}) =>
        dispatchToast({
          closable,
          message,
          variant: Variant.Success,
          ...defaultOptions,
          ...options,
        }),
      warning: (message = "", closable = true, options = {}) =>
        dispatchToast({
          closable,
          message,
          variant: Variant.Important,
          ...defaultOptions,
          ...options,
        }),
    };
  }, [dispatchToast]);

  return (
    <ToastContext.Provider value={toastContext}>
      {children}
    </ToastContext.Provider>
  );
};

const ToastProvider: React.FC<{
  children?: ReactNode;
  portalClassName?: string;
}> = ({ children, portalClassName }) => (
  <LGToastProvider portalClassName={portalClassName}>
    <ToastProviderCore>{children}</ToastProviderCore>
  </LGToastProvider>
);

export { ToastProvider, useToastContext };

import { useCallback } from "react";
import {
  RECENT_PAGE_SIZE_KEY,
  PaginationQueryParams,
} from "../../constants/pagination";
import { getDefaultPageSize } from "../../utils/pagination";
import { useQueryParam, useQueryParams } from "../useQueryParam";

/**
 * `usePagination` is a hook that manages the page and page size query params
 * It also saves the page size to local storage so that it can be remembered between sessions
 * Updating the page size will reset the page to 0
 * @returns - an object containing the current page, page size limit, and functions to update the page and page limit
 */
const usePagination = () => {
  const [queryParams, setQueryParams] = useQueryParams();
  const [page, setPage] = useQueryParam(PaginationQueryParams.Page, 0);
  const [limit] = useQueryParam(
    PaginationQueryParams.Limit,
    getDefaultPageSize(),
  );

  /**
   * `setLimit` updates the page size query param and saves the page size to local storage
   * @param pageSize - the new page size
   */
  const setLimit = useCallback(
    (pageSize: number) => {
      localStorage.setItem(RECENT_PAGE_SIZE_KEY, pageSize.toString());
      setQueryParams({
        ...queryParams,
        [PaginationQueryParams.Limit]: pageSize,
        [PaginationQueryParams.Page]: 0,
      });
    },
    [queryParams, setQueryParams],
  );

  return { page, limit, setLimit, setPage };
};

export default usePagination;

import {
  PAGE_SIZES,
  DEFAULT_PAGE_SIZE,
  RECENT_PAGE_SIZE_KEY,
} from "../../constants/pagination";

/**
 * Returns the most recent page size from local storage or the default page size
 * @returns The recent or default page size
 */
export const getDefaultPageSize = () => {
  const pageSizeFromLocalStorage = localStorage.getItem(RECENT_PAGE_SIZE_KEY);
  const pageSize = pageSizeFromLocalStorage
    ? parseInt(pageSizeFromLocalStorage, 10)
    : DEFAULT_PAGE_SIZE;

  return PAGE_SIZES.includes(pageSize) ? pageSize : DEFAULT_PAGE_SIZE;
};

